import { type SynapseEnhancedHttpClient } from "../utils/http.ts";
import { mapParams } from "../utils/api-mapping.ts";
import { validateString } from "../utils/validator.ts";
import { MatrixClientApi } from "../constants/api.ts";
import { handleApiResponse } from "../utils/response-formatter.ts";
import { BaseApi } from "../utils/base-api.ts";

export class FriendsVerificationApi extends BaseApi {
    public constructor(httpClient: SynapseEnhancedHttpClient) {
        super(httpClient);
    }

    public async removeFriend(friendId: string): Promise<boolean> {
        validateString(friendId, "friendId", { minLength: 1 });
        const mappedParams = mapParams({ friendId }, "friends");
        const response = await this.httpClient.delete<{
            status: string;
            error?: string;
        }>(`${MatrixClientApi.FRIENDS}/${encodeURIComponent(friendId)}`, mappedParams);

        handleApiResponse(response, "Failed to remove friend");
        return true;
    }
}
